INSERT INTO `response_templates` (`id`, `code`, `kind`, `label`, `subject`, `body`, `version`, `is_active`, `created_at`, `updated_at`) VALUES (1,'ACCUSE','accuse','Accusé de réception','Accusé de réception — réclamation {{reference}}','Madame, Monsieur {{client}},\n\nNous accusons réception de votre réclamation enregistrée sous la référence {{reference}}. Elle est en cours d\'examen par nos services.\nUne réponse vous sera apportée au plus tard le {{date_limite}}.\n\nBSCA Bank — Service réclamations',1,1,'2026-09-28 03:51:42','2026-09-28 03:51:42'),(2,'ATTENTE','attente','Réponse d\'attente','Suivi de votre réclamation {{reference}}','Madame, Monsieur {{client}},\n\nL\'instruction de votre réclamation {{reference}} nécessite des vérifications complémentaires. Nous revenons vers vous dans les meilleurs délais.\n\nBSCA Bank — Service réclamations',1,1,'2026-09-28 03:51:42','2026-09-28 03:51:42'),(3,'REPONSE','reponse','Réponse finale','Réponse à votre réclamation {{reference}}','Madame, Monsieur {{client}},\n\nÀ l\'issue de l\'examen de votre réclamation {{reference}}, nous vous informons de la décision suivante : [décision motivée].\n\nSi cette réponse ne vous satisfait pas, vous pouvez demander une réouverture depuis votre espace de suivi.\n\nBSCA Bank — Service réclamations',1,1,'2026-09-28 03:51:42','2026-09-28 03:51:42'),(4,'CLOTURE','cloture','Clôture du dossier','Clôture de votre réclamation {{reference}}','Madame, Monsieur {{client}},\n\nVotre réclamation {{reference}} est désormais clôturée. Nous vous remercions de votre confiance.\n\nBSCA Bank — Service réclamations',1,1,'2026-09-28 03:51:42','2026-09-28 03:51:42');
/*!40000 ALTER TABLE `response_templates` ENABLE KEYS */;
UNLOCK TABLES;

